cat > src/order.js <<'EOF'
// An order is a list of lines; amounts are in cents.
// Optional discountPercent (0-100, default 0) is a percentage off the whole order, applied before VAT.
function subtotal(order) { return order.lines.reduce((s, l) => s + l.unitCents * l.qty, 0); }
function discountPercent(order) {
  const p = order.discountPercent === undefined ? 0 : order.discountPercent;
  if (typeof p !== 'number' || !Number.isFinite(p) || p < 0 || p > 100) throw new Error('discountPercent must be between 0 and 100');
  return p;
}
function discount(order) { return Math.round(subtotal(order) * discountPercent(order) / 100); }
function discountedSubtotal(order) { return subtotal(order) - discount(order); }
module.exports = { subtotal, discountPercent, discount, discountedSubtotal };
EOF
cat > src/tax.js <<'EOF'
const { discountedSubtotal } = require('./order');
const RATE = 0.2; // VAT, charged on the order subtotal after any discount
function tax(order) { return Math.round(discountedSubtotal(order) * RATE); }
module.exports = { tax, RATE };
EOF
cat > src/invoice.js <<'EOF'
const { subtotal, discount } = require('./order');
const { tax } = require('./tax');
// Invoices are legal documents: each line shown here must reconcile with the totals.
function invoice(order) {
  const sub = subtotal(order); const d = discount(order); const t = tax(order);
  return { lines: order.lines, subtotalCents: sub, discountCents: d, taxCents: t, totalCents: sub - d + t };
}
module.exports = { invoice };
EOF
cat > src/refund.js <<'EOF'
const { RATE } = require('./tax');
const { discountPercent } = require('./order');
// Refund one order line: the line's price after the order discount, plus the VAT charged on it.
function refundLine(order, lineIndex, qty) {
  const line = order.lines[lineIndex];
  if (qty > line.qty) throw new Error('cannot refund more than was bought');
  const net = Math.round(line.unitCents * qty * (100 - discountPercent(order)) / 100);
  return net + Math.round(net * RATE);
}
module.exports = { refundLine };
EOF
cat >> test/shop.test.js <<'EOF'
const discounted = { ...order, discountPercent: 10 };
test('discount is taken before VAT and the invoice reconciles', () => {
  const i = invoice(discounted);
  assert.strictEqual(i.subtotalCents, 2500); assert.strictEqual(i.discountCents, 250);
  assert.strictEqual(i.taxCents, 450); assert.strictEqual(i.totalCents, 2700);
  assert.strictEqual(i.totalCents, i.subtotalCents - i.discountCents + i.taxCents);
});
test('no discount means discountCents is 0', () => assert.strictEqual(invoice(order).discountCents, 0));
test('discount rounds to the cent', () => {
  const i = invoice({ lines: [{ sku: 'c', unitCents: 999, qty: 1 }], discountPercent: 12.5 });
  assert.strictEqual(i.discountCents, 125); assert.strictEqual(i.taxCents, 175); assert.strictEqual(i.totalCents, 1049);
});
test('refund applies the order discount', () => assert.strictEqual(refundLine(discounted, 0, 1), 1080));
test('invalid discount is rejected', () => {
  for (const p of [-1, 101, NaN, '10']) assert.throws(() => invoice({ ...order, discountPercent: p }));
});
EOF
npm test 2>&1 | tail -15

